effect.shader:
// Pass 0: the wide 1D gaussian, evaluated into a quarter-res buffer with at most
//         64 half-taps. Stride scales with the requested tap count so the blur
//         extent (taps * texel) and the sigma mapping are unchanged.
// Pass 1: large radii read the buffer; small radii (where a quarter-res buffer
//         would lose crispness) use an exact full-res kernel, crossfaded 4..10 px.
const int MAX_WIDE_TAPS = 64;
const int MAX_NEAR_TAPS = 16;
vec4 s(vec2 uv){ return texture2DCv(inputImg.texture, uv); }
void main(){
  highp vec2 uv = acScreenNorm;
  highp vec2 texel = 1.0/max(getTexSize(inputImg.size), vec2(1.0));
  highp float r = wideRadius;
  if(r<=0.0){ gl_FragColor = s(uv); return; }
  highp float ftaps = floor(r * (quality==0?2.0:(quality==1?3.0:4.0)));
  highp float sigma = max(0.0001, r*0.6);
  highp float twoS2 = 2.0*sigma*sigma;

  if(acPass==0){
    highp float steps  = min(ftaps, float(MAX_WIDE_TAPS));
    highp float stride = ftaps/max(steps, 1.0);
    vec4 acc = s(uv);
    highp float wsum = 1.0;
    for(int k=1;k<=MAX_WIDE_TAPS;k++){
      highp float fk = float(k);
      if(fk>steps) break;
      highp float o = fk*stride;
      highp float wi = exp(-(o*o)/twoS2);
      if(wi<0.000001) break;
      highp vec2 d = vec2(o*texel.x, 0.0);
      acc  += (s(uv+d) + s(uv-d)) * wi;
      wsum += 2.0*wi;
    }
    gl_FragColor = acc/max(0.0001,wsum);
    return;
  }

  highp float mixWide = smoothstep(4.0, 10.0, r);
  if(mixWide >= 1.0){ gl_FragColor = texture2DCv(blurBuf.texture, uv); return; }

  highp float steps  = min(ftaps, float(MAX_NEAR_TAPS));
  highp float stride = ftaps/max(steps, 1.0);
  vec4 acc = s(uv);
  highp float wsum = 1.0;
  for(int k=1;k<=MAX_NEAR_TAPS;k++){
    highp float fk = float(k);
    if(fk>steps) break;
    highp float o = fk*stride;
    highp float wi = exp(-(o*o)/twoS2);
    if(wi<0.000001) break;
    highp vec2 d = vec2(o*texel.x, 0.0);
    acc  += (s(uv+d) + s(uv-d)) * wi;
    wsum += 2.0*wi;
  }
  vec4 near = acc/max(0.0001,wsum);
  if(mixWide <= 0.0){ gl_FragColor = near; return; }
  gl_FragColor = mix(near, texture2DCv(blurBuf.texture, uv), mixWide);
}
